// Chapters: Model Loading / Model I/O, Mesh, Model
// Loads a model file with Model I/O and draws it with Blinn-Phong lighting.
//
//     swift run ModelLoading /path/to/model.usdz     (or .obj)
//
// Without an argument it shows shapes generated by Model I/O instead.

import LearnMetalKit
import MetalKit
import ModelIO

struct FragmentUniforms {
    var lightPosition: Float3
    var viewPosition: Float3
    var baseColor: Float3
}

/// One MTKMesh with a texture per submesh and its transform inside the model.
struct Node {
    let mesh: MTKMesh
    let textures: [MTLTexture?]
    let baseColors: [Float3]
    let transform: float4x4
}

func loadModel(url: URL, device: MTLDevice) -> (nodes: [Node], normalize: float4x4) {
    let allocator = MTKMeshBufferAllocator(device: device)
    let asset = MDLAsset(url: url, vertexDescriptor: Geometry.modelIOVertexDescriptor, bufferAllocator: allocator)
    asset.loadTextures()
    let loader = MTKTextureLoader(device: device)

    let meshes: (modelIOMeshes: [MDLMesh], metalKitMeshes: [MTKMesh])
    do {
        meshes = try MTKMesh.newMeshes(asset: asset, device: device)
    } catch {
        fatalError("Could not load \(url.lastPathComponent): \(error)")
    }

    var nodes: [Node] = []
    for (mdlMesh, mtkMesh) in zip(meshes.modelIOMeshes, meshes.metalKitMeshes) {
        var textures: [MTLTexture?] = []
        var colors: [Float3] = []
        for submesh in (mdlMesh.submeshes as? [MDLSubmesh]) ?? [] {
            var texture: MTLTexture?
            var color = Float3(1, 1, 1)
            if let property = submesh.material?.property(with: .baseColor) {
                let options: [MTKTextureLoader.Option: Any] = [.generateMipmaps: true, .SRGB: false]
                switch property.type {
                case .texture:
                    if let mdlTexture = property.textureSamplerValue?.texture {
                        texture = try? loader.newTexture(texture: mdlTexture, options: options)
                    }
                case .URL:
                    if let textureURL = property.urlValue {
                        texture = try? loader.newTexture(URL: textureURL, options: options)
                    }
                case .float3:
                    color = property.float3Value
                case .float4:
                    let c = property.float4Value
                    color = Float3(c.x, c.y, c.z)
                default:
                    break
                }
            }
            textures.append(texture)
            colors.append(color)
        }

        // Multiply the local transforms from the mesh up to the root.
        var transform = float4x4.identity
        var current: MDLObject? = mdlMesh
        while let object = current {
            if let local = object.transform { transform = local.matrix * transform }
            current = object.parent
        }
        nodes.append(Node(mesh: mtkMesh, textures: textures, baseColors: colors, transform: transform))
    }

    // Scale and center any model into a box two units wide.
    let bounds = asset.boundingBox
    let size = bounds.maxBounds - bounds.minBounds
    let center = (bounds.maxBounds + bounds.minBounds) * 0.5
    let scale = 2 / max(size.x, max(size.y, size.z), 0.0001)
    return (nodes, float4x4(scale: scale) * float4x4(translation: -center))
}

func generatedShapes(device: MTLDevice) -> [Node] {
    let allocator = MTKMeshBufferAllocator(device: device)
    let sphere = MDLMesh(sphereWithExtent: [0.6, 0.6, 0.6], segments: [48, 48],
                         inwardNormals: false, geometryType: .triangles, allocator: allocator)
    let box = MDLMesh(boxWithExtent: [1, 1, 1], segments: [1, 1, 1],
                      inwardNormals: false, geometryType: .triangles, allocator: allocator)
    let shapes: [(MDLMesh, Float3, Float3)] = [
        (sphere, [-0.9, 0, 0], [0.9, 0.5, 0.3]),
        (box, [0.9, 0, 0], [0.35, 0.55, 0.85]),
    ]
    return shapes.map { (mesh, position, color) -> Node in
        mesh.vertexDescriptor = Geometry.modelIOVertexDescriptor
        return Node(mesh: try! MTKMesh(mesh: mesh, device: device), textures: [nil], baseColors: [color],
                    transform: float4x4(translation: position))
    }
}

final class Renderer: BaseRenderer {
    let pipelineState: MTLRenderPipelineState
    let depthState: MTLDepthStencilState
    let samplerState: MTLSamplerState
    let fallbackTexture: MTLTexture
    let nodes: [Node]
    let normalize: float4x4

    init(view: MTKView) {
        let device = view.device!
        depthState = makeDepthState(device: device)
        samplerState = makeSampler(device: device)
        fallbackTexture = Textures.checker(device: device, a: [1, 1, 1, 1], b: [0.8, 0.8, 0.8, 1])

        if CommandLine.arguments.count > 1 {
            let model = loadModel(url: URL(fileURLWithPath: CommandLine.arguments[1]), device: device)
            nodes = model.nodes
            normalize = model.normalize
        } else {
            nodes = generatedShapes(device: device)
            normalize = .identity
        }

        let library = makeShaderLibrary(device: device, bundle: .module)
        pipelineState = makePipeline(device: device, library: library,
                                     vertex: "vertex_main", fragment: "fragment_main",
                                     colorFormats: [view.colorPixelFormat], depthFormat: .depth32Float,
                                     vertexDescriptor: Geometry.packedVertexDescriptor)
        super.init(view: view)
        view.clearColor = MTLClearColor(red: 0.12, green: 0.13, blue: 0.16, alpha: 1)
        camera.position = [0, 0.8, 3.5]
        camera.pitch = -12
    }

    override func render(in view: MTKView, commandBuffer: MTLCommandBuffer) {
        guard let passDescriptor = view.currentRenderPassDescriptor,
              let encoder = commandBuffer.makeRenderCommandEncoder(descriptor: passDescriptor) else { return }

        encoder.setRenderPipelineState(pipelineState)
        encoder.setDepthStencilState(depthState)
        encoder.setFragmentSamplerState(samplerState, index: 0)

        let spin = float4x4(rotation: time * 0.5, axis: [0, 1, 0])
        for node in nodes {
            encoder.setVertexValue(sceneUniforms(model: spin * normalize * node.transform), index: 1)
            for (index, vertexBuffer) in node.mesh.vertexBuffers.enumerated() {
                encoder.setVertexBuffer(vertexBuffer.buffer, offset: vertexBuffer.offset, index: index)
            }
            for (index, submesh) in node.mesh.submeshes.enumerated() {
                let color = index < node.baseColors.count ? node.baseColors[index] : Float3(1, 1, 1)
                let texture = index < node.textures.count ? node.textures[index] : nil
                encoder.setFragmentValue(FragmentUniforms(lightPosition: [2, 3, 3],
                                                          viewPosition: camera.position,
                                                          baseColor: color), index: 1)
                encoder.setFragmentTexture(texture ?? fallbackTexture, index: 0)
                encoder.drawIndexedPrimitives(type: submesh.primitiveType,
                                              indexCount: submesh.indexCount,
                                              indexType: submesh.indexType,
                                              indexBuffer: submesh.indexBuffer.buffer,
                                              indexBufferOffset: submesh.indexBuffer.offset)
            }
        }
        encoder.endEncoding()
    }
}

runApp(title: "11 Model Loading") { view in Renderer(view: view) }
